import logging

from taf.fdsw.rc.clients.exceptions import TimeoutExceeded
from taf.fdsw.rc.interfaces.FDSW21D.swm import SoftwareManagement21D

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SoftwareManagement22A(SoftwareManagement21D):

    def __init__(self, client):
        super(SoftwareManagement22A, self).__init__(client)

    def trigger_factory_reset(self, sw_slot_id, timeout=10):
        try:
            self._client.send(method='software.factoryReset',
                              parameters={"slotId": str(sw_slot_id)},
                              timeout=timeout)
        except TimeoutExceeded:
            logging.info('Restoring slot {} to factory settings'.format(sw_slot_id))
